/** Actual checker bytes through the complete composition. Ephemeral protocol
 * authorities below do not register or certify a production language method. */
class SemanticEmbeddedPublicationTest {
    @TempDir Path directory;
    StreamingContentStore content;SemanticTables tables;
    ContentHandle put(Object value)throws IOException{return content.put(new ByteArrayInputStream(CanonicalJson.write(value).getBytes(StandardCharsets.UTF_8)),()->false);}
    ContentHandle bytes(Path path)throws IOException{try(var input=Files.newInputStream(path)){return content.put(input,()->false);}}
    Map<String,Object> read(Path path)throws IOException{return GraphJson.object(GraphJson.read(Files.readString(path,StandardCharsets.UTF_8),GraphJson.Limits.defaults()));}
    static ContentDigest digest(String value){return ContentDigest.sha256Utf8(value);}
    static EvidenceVerifier.Method method(String id,String predicate,ContentDigest tool,List<String> checks){return new EvidenceVerifier.Method(new VersionedIdentifier("authored.protocol."+id,"v1"),new VersionedIdentifier("polyglot."+predicate,"m8.4-v1"),tool,checks);}
    final class Authority {
        final KeyPair controller,validator;final EvidenceVerifier verifier;final Path root;
        final List<EvidenceVerifier.Method> methods;final Map<String,Object> configuration;
        Authority(ContentDigest nativeTool,ContentDigest mappedTool,ContentDigest correspondenceTool,ContentDigest rootTool)throws Exception{
            var generator=KeyPairGenerator.getInstance("Ed25519");controller=generator.generateKeyPair();validator=generator.generateKeyPair();root=directory.resolve("operator");Files.createDirectories(root.resolve("claims"));
            var census=List.of("INDEPENDENT_CENSUS","DOCUMENT_MEMBERSHIP","CATEGORY_CLOSURE");var observations=List.of("CALLER_TARGET_ORIGIN","SOURCE_COORDINATES","APPLICABILITY_VALIDATED");
            methods=List.of(method("native-census","census",nativeTool,census),method("native-observations","observations",nativeTool,observations),method("mapped-census","census",mappedTool,census),method("mapped-observations","observations",mappedTool,observations),method("correspondence","correspondence",correspondenceTool,SemanticCorrespondence.CHECKS),method("root","root-census",rootTool,List.of("SEALED_SOURCE_MEMBERSHIP","EFFECTIVE_CONTEXT_CLOSURE","GENERATED_EXTERNAL_LINEAGE","EMBEDDED_SOURCE_MAPPING")));
            verifier=new EvidenceVerifier(Map.of("controller",controller.getPublic()),Map.of("validator",validator.getPublic()),methods);
            configuration=new TreeMap<>(Map.of("schema","semantic-authority:m8.4-v1","controllers",Map.of("controller",Base64.getEncoder().encodeToString(controller.getPublic().getEncoded())),"validators",Map.of("validator",Base64.getEncoder().encodeToString(validator.getPublic().getEncoded())),"methods",methods,"revoked",List.of()));saveConfiguration();
        }
        void saveConfiguration()throws IOException{Files.writeString(root.resolve("authority.json"),CanonicalJson.write(configuration));}
        EvidenceVerifier.Method named(String name){return methods.stream().filter(m->m.method().id().equals("authored.protocol."+name)).findFirst().orElseThrow();}
        Map<String,Object> issue(String name,ContentDigest scope,ContentDigest inputs,Object payload)throws Exception{
            var method=named(name);var claim=put(payload);var expected=new EvidenceVerifier.Expected(digest("AUTHORED_PROTOCOL_LAUNCH"),digest("AUTHORED_PROTOCOL_PROFILE"),1,scope,inputs,claim,method.method(),method.predicate(),method.tool());
            var receipt=new EvidenceVerifier.Receipt("execution-protected-receipt:m8.4-v1","AUTHORED_PROTOCOL_KEYS_ONLY",1,expected.launch(),expected.profile(),digest("protocol-output"),digest("protocol-materials"),digest("protocol-termination"));var attestation=new EvidenceVerifier.Attestation("execution-protected-attestation:m8.4-v1",receipt.identity(),claim.digest(),scope,inputs,method.tool(),method.method(),method.predicate(),method.requiredChecks(),true);
            return Map.of("expected",expected,"receipt",receipt,"controllerSignature",sign("controller",receipt,controller.getPrivate()),"attestation",attestation,"validatorSignature",sign("validator",attestation,validator.getPrivate()));
        }
        void bundle(ContentDigest key,Map<String,Object> claims)throws IOException{Files.writeString(root.resolve("claims").resolve(key.value().substring(7)+".json"),CanonicalJson.write(Map.of("schema","semantic-signed-claims:m8.4-v1","claims",claims)));}
        Map<String,Object> revision(String prefix,LanguageSemanticRequest request,SemanticTables.Table output)throws Exception{return new TreeMap<>(Map.of("census",issue(prefix+"-census",request.scope(),request.inputClosure(),SemanticReconciler.proofPayload(request,output)),"observations",issue(prefix+"-observations",request.scope(),request.inputClosure(),SemanticReconciler.proofPayload(request,output))));}
    }
    static EvidenceVerifier.SignatureEnvelope sign(String id,Object value,PrivateKey key)throws Exception{var signature=Signature.getInstance("Ed25519");signature.initSign(key);signature.update(CanonicalJson.write(Map.of("keyId",id,"payload",value)).getBytes(StandardCharsets.UTF_8));return new EvidenceVerifier.SignatureEnvelope(id,Base64.getEncoder().encodeToString(signature.sign()));}

    @Test void nativeEmbeddedCrossProviderHistoryColdPublicationAndRevocationCompose()throws Exception{
        content=new StreamingContentStore(directory.resolve("cas"));tables=new SemanticTables(content,65536);
        var fixture=Path.of("..","analyzer","src","test","resources","polyglot","typescript-embedded-v1").toRealPath();var metadata=read(fixture.resolve("fixture.json"));assertEquals("HOST_AUTHORED_FIXTURE_ONLY",metadata.get("execution"));var generatedBytes=bytes(fixture.resolve("main.ts"));var originalBytes=bytes(fixture.resolve("component.vue"));var capture=CapturedSemanticProvider.read(bytes(fixture.resolve("capture.ndjson")),tables,content,65536,()->false);
        var rootTool=digest("authored-exact-embedded-root-validator");var correspondenceTool=digest("authored-exact-question-correspondence");var authority=new Authority(capture.toolset(),CanonicalJson.sha256(List.of(SourceMappedSemanticProvider.PROVIDER,capture.toolset())),correspondenceTool,rootTool);var policy=authority.verifier.policyIdentity();
        var inventory=new ContentDigest(GraphJson.string(metadata.get("inventory")));var context=EvidenceContext.forSnapshot(SnapshotIdentity.from(RepositoryIdentity.fromCanonicalCoordinate("urn:test:typescript-native"),inventory));var request=new LanguageSemanticRequest(context,inventory,"root","app","main","baseline","typescript","5.9.3",capture.documents(),capture.census(),put(Map.of("execution","HOST_AUTHORED_FIXTURE_ONLY","export",capture.export())),new VersionedIdentifier("frontend.typescript-capture","m8.4-v1"),capture.toolset(),policy,digest("authored-worker-policy"));assertEquals(capture.scope(),request.scope());
        var nativeOutput=new CapturedSemanticProvider(capture,tables,content).analyze(request,()->false);var map=EmbeddedSourceMap.from(read(fixture.resolve("source-map.json")));assertEquals(generatedBytes,map.generated().content());assertEquals(originalBytes,map.originals().get("component.vue").content());var mapHandle=put(map);var maps=tables.write(SemanticTables.Kind.DOCUMENT,List.of(new SemanticTables.Row(SemanticTables.Kind.DOCUMENT,"main.ts",request.scope(),Map.of("map",mapHandle))).iterator(),()->false);SemanticContextCoordinator.CensusIndex indexes=()->SqliteSemanticCensusIndex.temporary(directory.resolve("scratch"),65536);
        var provider=SourceMappedSemanticProvider.create(request,nativeOutput,maps,content,tables,indexes,()->false);var target=provider.request();var output=provider.analyze(target,()->false);
        var bindings=new ArrayList<SemanticTables.Row>();try(var questions=tables.open(target.census(),()->false);var observed=tables.open(output,()->false)){SemanticTables.Row question;while((question=questions.next())!=null){var observation=observed.next();assertEquals(question.key(),observation.key());bindings.add(new SemanticTables.Row(SemanticTables.Kind.CENSUS,question.key(),target.inputClosure(),Map.of("source",question.key(),"sourceIdentity",question.identity(),"target",question.identity(),"observation",put(observation),"reason","AUTHORED_EXACT_SAME_SYNTAX_QUESTION")));}assertNull(observed.next());}
        var correspondenceMap=put(Map.of("schema","semantic-correspondence:m8.4-v1","source",request.identity(),"target",target.identity(),"questions",tables.write(SemanticTables.Kind.CENSUS,bindings.iterator(),()->false),"tool",correspondenceTool));var correspondence=new SemanticCorrespondence(content,tables,indexes);var projected=correspondence.project(target,request,nativeOutput,correspondenceMap,()->false);assertEquals(output,projected.observations());
        var nativeClaims=authority.revision("native",request,nativeOutput);nativeClaims.put("correspondence:"+correspondenceMap.digest().value(),authority.issue("correspondence",target.scope(),SemanticCorrespondence.inputClosure(target,request,nativeOutput,projected),SemanticCorrespondence.proofPayload(target,request,nativeOutput,projected)));authority.bundle(SemanticAuthorityStore.revisionKey(request,nativeOutput),nativeClaims);authority.bundle(SemanticAuthorityStore.revisionKey(target,output),authority.revision("mapped",target,output));var configured=new SemanticAuthorityStore(authority.root,content,tables,policy);
        var ledger=new SemanticAnswerLedger(content,tables,Optional.of(indexes));var history=ledger.appendMapped(target,request,nativeOutput,correspondenceMap,Optional.empty(),()->false);
        var path=LogicalPath.utf8("component.vue");var source=new SemanticTables.Row(SemanticTables.Kind.DOCUMENT,path.key(),inventory,Map.of("rawPath",path.rawBase64(),"kind","FILE","population","MAIN","disposition","ACQUIRED","content",originalBytes));var entries=tables.write(SemanticTables.Kind.DOCUMENT,List.of(source).iterator(),()->false);var coordinator=new SemanticContextCoordinator(content,tables);var plan=coordinator.plan(context,new PolyglotInventory.Report(inventory,entries,1,0),List.of(new SemanticContextCoordinator.Selection("embedded",target)).iterator(),policy,()->false);
        SemanticTables.Row document;try(var docs=tables.open(target.documents(),()->false)){document=docs.next();assertNotNull(document);assertNull(docs.next());}
        var input=new SemanticRootCensus.Input(tables.write(SemanticTables.Kind.CENSUS,List.of(new SemanticTables.Row(SemanticTables.Kind.CENSUS,path.key(),plan.identity(),Map.of("entry",source.identity(),"disposition","REQUIRED","reason","AUTHORED_SCRIPT_REGION","evidence",mapHandle))).iterator(),()->false),tables.write(SemanticTables.Kind.CONTEXT,List.of(new SemanticTables.Row(SemanticTables.Kind.CONTEXT,"embedded",plan.identity(),Map.of("disposition","SELECTED","request",target.identity(),"reason","AUTHORED_FIXED_CONTEXT","evidence",mapHandle))).iterator(),()->false),tables.write(SemanticTables.Kind.DOCUMENT,List.of(new SemanticTables.Row(SemanticTables.Kind.DOCUMENT,SemanticRootCensus.documentKey("embedded","main.ts"),plan.identity(),Map.of("context","embedded","document","main.ts","documentIdentity",document.identity(),"origin","EMBEDDED","source",path.key(),"content",generatedBytes,"lineage",mapHandle))).iterator(),()->false),rootTool);
        SemanticRootCensus.Result rootCensus;try(var index=indexes.open()){rootCensus=new SemanticRootCensus(content,tables).reconcile(plan,input,index,Optional.empty(),Set.of(),()->policy,()->false);}assertTrue(rootCensus.structurallyClosed());assertEquals(1,rootCensus.accounting().embedded());authority.bundle(SemanticAuthorityStore.rootKey(plan,input),Map.of("root",authority.issue("root",plan.identity(),SemanticRootCensus.inputClosure(plan,input),SemanticRootCensus.proofPayload(plan,input,rootCensus.accounting()))));var rootProof=configured.rootClaim(plan,input);
        var result=coordinator.runWithRootCensus(plan,r->Optional.of(provider),configured::revisionClaims,r->Optional.of(history),Optional.of(new SemanticContextCoordinator.RootCensus(input,indexes,rootProof)),Map.of(),Set.of(),()->policy,c->{},()->false);assertTrue(result.selectionQualified());assertFalse(result.complete(),"Authenticated native output still contains the explicit implicit-generation gap");assertEquals(1,result.incomplete());
        var heads=directory.resolve("heads");var publications=new SemanticPublicationStore(heads,content,tables,Optional.of(configured.validation(indexes)));var published=publications.commit(plan,result,Optional.empty(),()->policy,()->false);var cold=new SemanticPublicationStore(heads,new StreamingContentStore(directory.resolve("cas")),new SemanticTables(content,65536),Optional.of(new SemanticAuthorityStore(authority.root,content,tables,policy).validation(indexes)));assertEquals(published,cold.load(plan.identity(),()->policy,()->false).orElseThrow());assertThrows(IOException.class,()->new SemanticPublicationStore(heads,content,tables).load(plan.identity(),()->policy,()->false));
        var queries=cold.queries(()->policy);var summary=queries.summary(plan.identity(),()->false);assertEquals("VALIDATED_OBSERVATION",summary.trust());assertFalse(summary.complete());assertEquals("1",summary.accounting().get("embedded"));var child=queries.contexts(plan.identity(),10,Optional.empty(),()->false).items().getFirst();assertEquals("PARTIAL",child.state());assertEquals("2",child.answers().get("historyRevisions"));assertEquals("LIVE_VALIDATED_CURRENT",child.answers().get("availability"));assertEquals(2,queries.answers(plan.identity(),"embedded","HISTORY",10,Optional.empty(),()->false).items().size());
        var mapProof=configured.revisionClaims(request,nativeOutput).get("correspondence:"+correspondenceMap.digest().value());authority.configuration.put("revoked",List.of(mapProof.identity()));authority.saveConfiguration();assertThrows(IOException.class,()->cold.load(plan.identity(),()->policy,()->false));assertThrows(IOException.class,()->queries.summary(plan.identity(),()->false));assertEquals(published,cold.head(plan.identity()).orElseThrow());
    }
}
